  assert.equal(mmddToDate(807, 2026), "2026-08-07");
  assert.equal(mmddToDate(724, 2026), "2026-07-24"); // a non-August date still round-trips
  assert.equal(mmddToDate(1231, 2026), "2026-12-31");
});

